import json,hashlib,sys
from pathlib import Path
E=Path(__file__).resolve().parent;J=E.parent;R=next(p for p in E.parents if (p/'scripts/generator_review.py').exists());W=J/'workspace'
sys.path.insert(0,str(R/'scripts'))
from generator_packages import package_digest
from generator_pipeline import digest
read=lambda p:json.loads(Path(p).read_text())
write=lambda n,d:(E/n).write_text(json.dumps(d,indent=2)+'\n')
b=read(E/'final-binding.json');m=read(W/'package.json')
actual=package_digest(W,m['entrypoint'],m['files'],dependencies=m['dependencies']);assert actual==b['package_hash']
paths=list((R/'engine/rust').rglob('*.rs'))+[R/'generate/runs/current/check-engine']
engine=digest({str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths});assert engine==b['engine_hash']
assert digest(read(J/'source/source.json'))==b['source_hash'];assert digest(read(J/'source/inventory.json'))==b['inventory_hash']
levels=read(J/'source/source.json')['material']['kp'][':knowledge-point/level-coverage'];assert levels==[{':db/ident':':question.difficulty/easy'}]
batches={}
for band,row in b['verification_batches'].items():
 rs=read(J/('samples.json' if band=='hard' else 'samples-'+band+'.json'));assert digest(rs)==row['batch_hash'];assert rs==read(E/('final-'+band+'.json'));assert len(rs)==row['count']
 survivors=read(E/('delivery-final-'+band)/'accepted.json');assert len(survivors)==len(rs)
 rendering=read(E/('render-'+band)/'rendering.json');assert rendering['passed'] and len(rendering['cases'])==len(rs)
 batches[band]={'count':len(rs),'batch_hash':digest(rs),'delivered_survivors':len(survivors),'rendered':len(rendering['cases']),'sample_refs':['final-'+band+'.json','delivery-final-'+band+'/accepted.json']}
write('final-freeze.json',{'status':'passed','binding':b,'current_package_hash':actual,'current_engine_hash':engine,'batches':batches,'imported_level_coverage_unchanged':levels,'database_writes':0,'package_changes_this_session':[],'shared_changes_this_session':[],'provenance':'provenance.json','limitation':'Captured inventory basis7581; publication and subsequent learner history remain runner-owned.'})
write('visual-inspection.json',{'status':'passed','screenshots_examined':['render-easy/question-002.png','render-moderate/question-003.png','render-hard/question-002.png','render-controls/question-019.png','render-controls/question-014.png','render-negative-constants/question-001.png'],'observations':['Actual UI displays prompt equations, two numeric controls and signed or supplied-sign values correctly in every band.','Three aligned derivation rows, underbrace, exact fractions and cancellation are visible.','Bold Add and subtract, italic source words and Solution label render with emphasis and no literal stars.','Source radio preview retains all five full expressions and its correct completed result.','Variable rename, hard positive residual and negative original-constant controls render consistently with the changed givens.','No tables, matrix partition lines, diagrams, currencies or percentages occur in these source/generated families.'],'all_preview_checks':'render-boundary-checks.json','scope':'46 previews: every final item and source/counterfactual/matched/canonical/negative-constant controls; intended prose math and three ordinary derivation rows counted in actual rendered DOM.'})
analysis=read(E/'source-analysis.json');analysis={k:v for k,v in analysis.items() if k!='independent_judgment'}
report={'verdict':'accepted','summary':'Retained the existing constant-catalog repair and independently verified all three final bands against the current engine. All14 final records survive delivery; no unresolved defects remain.','source_analysis':analysis,'checks':{},'findings':[],'band_verification':{}}
def check(name,refs,details):report['checks'][name]={'status':'passed','evidence_paths':refs,'details':details}
check('source_replay',['source-replay-checks.json','source-path-checks.json','canonical-check.json','provenance.json'],'Five complete imports and three published investigation exemplars reproduce normalized prompts, banks, keys and solutions. Canonical and partial-source mathematical inputs checked; imports remain unchanged.')
check('math',['independent-math.json','source-path-checks.json','canonical-check.json'],'Exact independent expansion checks74 ordinary records, including all14 final records, plus eight source/exemplar replays. Every shown derivation row and keyed numeric fragment agrees.')
check('variety',['catalog-before.txt','catalog-after.txt','repair-summary.json','delivery-summary.json'],'The saved pre-repair generator fails the source-constant regression; the current catalog passes in every band. Source-style constants, cancellation and all residual signs remain eligible. No further package edit was necessary.')
check('decision_variation',['pedagogical-variation.json','shortcut-measurements.json','counterfactual-results.json','selection-analysis.json'],'Relevant constant/coefficient changes update both completion outputs and reject stale answers; renaming preserves numeric responses.150 declared surface/intended-skill probes cover final/control inputs and actual survivors, including conditional cue groups. No ordinary choice bank exists.')
check('scope',['solution-paths.json','negative-scope.json','source-path-checks.json'],'Each served response shape is traced through displayed completion to its exact field scope. Hard reordering and signed-parameter comparison are explicit. An algebraically equivalent but unshown reversed-binomial control fails the path check.')
check('grading',['grading-input.json','grading-report.json','canonical-grading-input.json','canonical-grading-report.json'],'Current native learner engine passes974 checks: exact/equivalent fractions, decimal and trailing-zero spellings, nearby wrong values, sign errors, all replay choices and stale counterfactual keys.')
check('rendering',['render-easy/rendering.json','render-moderate/rendering.json','render-hard/rendering.json','render-controls/rendering.json','render-negative-constants/rendering.json','render-boundary-checks.json','visual-inspection.json'],'All46 actual UI previews pass. Shared prose validation and rendered-DOM equation/row accounting supplement screenshot inspection; equations, answer controls and emphasis survive correctly in every final band.')
check('packaging',['packaging.json','finalize-command.json','final-binding.json','final-freeze.json'],'Exact Python3.13.5 standard-library dependency contract matches. Declared package relocates and deterministically replays all three final seeds/counts. Final package, engine, source, inventory and batch hashes verified; imported coverage unchanged.')
check('progression',['progression.json','matched-difficulty.json','final-easy.json','final-moderate.json','final-hard.json'],'At matched arithmetic, easy supplies a procedure hint; moderate requires retrieving it; hard requires recognizing reordered terms and interpreting both signed parameters. All retain both completion operations. Moderate/hard are defensible authored placements, with only easy imported calibration.')
for band,row in b['verification_batches'].items():
 report['band_verification'][band]={'status':'passed','batch_sha256':row['batch_hash'],'evidence_paths':['final-'+band+'.json','delivery-final-'+band+'/delivery.json','independent-math.json','grading-report.json','render-'+band+'/rendering.json','render-boundary-checks.json','shortcut-measurements.json','final-freeze.json'],'details':str(row['count'])+'/'+str(row['count'])+' final items survive captured-inventory delivery and pass exact math, native grading, actual UI rendering and applicable conditional shortcut/coverage checks. Includes negative, zero and positive residuals.'}
write('final-result.json',report)
(E/'session-state.md').write_text('All nine checks and all three final bands complete. Existing catalog repair independently reproduced before/after.974 native checks and46 actual UI previews pass. Package/engine/source/inventory/batch identities frozen; imports and coverage unchanged. Final report written; next validate the report contract.\n')
print(json.dumps({'status':'passed','bands':batches,'native_checks':974,'ui_previews':46}))
